//! Every routine in the program whose whole job is letting one thing go.
//!
//! The compiler puts one of these behind any function that holds something
//! releasable: a landing pad that runs when the function is left, however it is
//! left, and releases exactly one thing at exactly one place in the frame.
//! There are 11442 of them still to account for, which is a large share of what is
//! left of the program, and they are all the same shape.
//!
//! Individually they say nothing at all. Together they are a map of how the
//! program keeps things on the stack: which of the several kinds of release is
//! needed, how many things are let go at once, and — the part worth having —
//! where in a frame things are kept. The offsets are not spread evenly. A
//! handful of places account for most of the program, which is what a compiler
//! that lays out frames the same way every time produces, and it is the sort of
//! regularity that makes a decompiled binary readable at all.

// The addresses are written without separators so the port-mapping importer can
// match them against the recovered functions.
#![allow(clippy::unreadable_literal)]

/// What one landing pad lets go of.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Releases {
    /// Nothing — the pad exists but has nothing to do.
    Nothing,
    /// A string of the program's own wide kind.
    OwnWideString,
    /// One of the narrow kind.
    NarrowString,
    /// One of the platform's kind.
    PlatformString,
    /// An interface reference.
    Interface,
    /// A value cell, emptied.
    Cell,
    /// An object, freed through its own destructor.
    Object,
    /// An array whose length is kept in front of it.
    DynamicArray,
    /// An array of records, each finalised in turn.
    ArrayOfRecords,
    /// Whatever a type description says is there.
    ByType,
}

/// One group of landing pads that do the same thing.
#[derive(Debug, Clone, Copy)]
pub struct PadGroup {
    /// What they let go of.
    pub releases: Releases,
    /// Where in the frame it is kept.
    ///
    /// Wider than it looks as though it needs to be: two frames in the
    /// program are large enough that the thing being let go of sits more than
    /// sixty-four kilobytes in.
    pub offset: u32,
    /// How many are let go at once.
    pub several: u8,
    /// Whether the frame holds a pointer to the thing rather than the thing.
    pub through_a_pointer: bool,
    /// Every pad that does it.
    pub members: &'static [u32],
}

