/// How many pads are accounted for here.
pub const PAD_COUNT: usize = 11442;

/// Implements part of the landing-pad family.
///
/// Every group that lets go of one kind of thing.
#[must_use]
pub fn groups_releasing(releases: Releases) -> Vec<&'static PadGroup> {
    PAD_GROUPS
        .iter()
        .filter(|group| group.releases == releases)
        .collect()
}

/// Implements part of the landing-pad family.
///
/// How many pads there are altogether.
#[must_use]
pub fn counted() -> usize {
    PAD_GROUPS.iter().map(|group| group.members.len()).sum()
}

/// Implements part of the landing-pad family.
///
/// The places in a frame that anything is held at, commonest first.
#[must_use]
pub fn offsets_in_use() -> Vec<(u32, usize)> {
    let mut counted: Vec<(u32, usize)> = Vec::new();
    for group in PAD_GROUPS {
        if group.releases == Releases::Nothing {
            continue;
        }
        match counted.iter_mut().find(|(at, _)| *at == group.offset) {
            Some((_, seen)) => *seen += group.members.len(),
            None => counted.push((group.offset, group.members.len())),
        }
    }
    counted.sort_by(|left, right| right.1.cmp(&left.1).then(left.0.cmp(&right.0)));
    counted
}

/// Implements part of the landing-pad family.
///
/// What share of the pads sit at the commonest few places.
#[must_use]
pub fn share_at_the_commonest(places: usize) -> f64 {
    let counted = offsets_in_use();
    let held: usize = counted.iter().map(|(_, seen)| *seen).sum();
    if held == 0 {
        return 0.0;
    }
    let top: usize = counted.iter().take(places).map(|(_, seen)| *seen).sum();
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few thousand, well inside what a double holds exactly"
    )]
    {
        top as f64 / held as f64
    }
}

/// Implements part of the landing-pad family.
///
/// Whether a pad at this address is known, and what it does.
#[must_use]
pub fn pad_at(routine: u32) -> Option<&'static PadGroup> {
    PAD_GROUPS
        .iter()
        .find(|group| group.members.binary_search(&routine).is_ok())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_groups_hold() {
        assert_eq!(counted(), PAD_COUNT);
        assert!(PAD_GROUPS.len() > 100);
    }

    #[test]
    fn no_pad_is_listed_twice_anywhere() {
        let mut routines: Vec<u32> = PAD_GROUPS
            .iter()
            .flat_map(|group| group.members.iter().copied())
            .collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }

    #[test]
    fn every_group_is_sorted_so_it_can_be_searched() {
        for group in PAD_GROUPS {
            assert!(
                group.members.windows(2).all(|pair| pair[0] < pair[1]),
                "{:?} {:#x}",
                group.releases,
                group.offset
            );
        }
    }

    #[test]
    fn no_group_is_empty() {
        for group in PAD_GROUPS {
            assert!(!group.members.is_empty(), "{:?}", group.releases);
        }
    }

    #[test]
    fn a_pad_that_does_nothing_holds_nothing_and_is_at_no_offset() {
        for group in groups_releasing(Releases::Nothing) {
            assert_eq!(group.offset, 0);
            assert_eq!(group.several, 0);
        }
    }

    #[test]
    fn every_other_pad_lets_go_of_at_least_one_thing() {
        for group in PAD_GROUPS {
            if group.releases != Releases::Nothing {
                assert!(group.several >= 1, "{:?}", group.releases);
            }
        }
    }

    #[test]
    fn every_offset_is_a_whole_number_of_words_into_the_frame() {
        for group in PAD_GROUPS {
            assert_eq!(group.offset % 8, 0, "{:#x}", group.offset);
        }
    }

    #[test]
    fn two_frames_are_too_large_for_a_sixteen_bit_offset() {
        // Which is why the offset is held wider than it looks as though it
        // needs to be.
        let huge = PAD_GROUPS
            .iter()
            .map(|group| group.offset)
            .filter(|offset| u16::try_from(*offset).is_err())
            .count();

        assert_eq!(huge, 2);
    }

    #[test]
    fn the_commonest_kind_of_thing_released_is_a_string() {
        let mut counted: Vec<(Releases, usize)> = Vec::new();
        for group in PAD_GROUPS {
            match counted.iter_mut().find(|(kind, _)| *kind == group.releases) {
                Some((_, seen)) => *seen += group.members.len(),
                None => counted.push((group.releases, group.members.len())),
            }
        }
        counted.sort_by_key(|(_, seen)| std::cmp::Reverse(*seen));

        assert!(matches!(
            counted[0].0,
            Releases::OwnWideString | Releases::Nothing
        ));
    }

    #[test]
    fn a_handful_of_places_account_for_most_of_the_program() {
        // Which is what a compiler laying out frames the same way every time
        // produces.
        let counted = offsets_in_use();

        assert!(counted.len() > 10);
        assert!(share_at_the_commonest(6) > 0.6, "{:?}", &counted[..6]);
    }

    #[test]
    fn the_commonest_place_of_all_is_used_by_more_than_one_kind_of_release() {
        let commonest = offsets_in_use()[0].0;
        let mut kinds: Vec<Releases> = PAD_GROUPS
            .iter()
            .filter(|group| group.offset == commonest && group.releases != Releases::Nothing)
            .map(|group| group.releases)
            .collect();
        kinds.sort_unstable();
        kinds.dedup();

        assert!(kinds.len() > 1, "{kinds:?}");
    }

    #[test]
    fn some_pads_let_go_of_several_things_at_once() {
        let several: usize = PAD_GROUPS
            .iter()
            .filter(|group| group.several > 1)
            .map(|group| group.members.len())
            .sum();

        assert!(several > 100);
    }

    #[test]
    fn and_letting_go_of_several_is_only_ever_done_with_strings() {
        for group in PAD_GROUPS.iter().filter(|group| group.several > 1) {
            assert!(
                matches!(
                    group.releases,
                    Releases::OwnWideString | Releases::NarrowString
                ),
                "{:?}",
                group.releases
            );
        }
    }

    #[test]
    fn a_pad_can_be_found_by_its_address() {
        let known = PAD_GROUPS[0].members[0];

        assert!(pad_at(known).is_some());
        assert!(pad_at(0).is_none());
        assert!(pad_at(0xFFFF_FFFF).is_none());
    }

    #[test]
    fn and_what_is_found_is_the_group_that_holds_it() {
        for group in PAD_GROUPS.iter().take(20) {
            let found = pad_at(group.members[0]).expect("it is listed");

            assert_eq!(found.releases, group.releases);
            assert_eq!(found.offset, group.offset);
        }
    }

    #[test]
    fn the_share_at_no_places_is_nothing_and_at_all_of_them_is_everything() {
        assert!((share_at_the_commonest(0) - 0.0).abs() < f64::EPSILON);
        let all = offsets_in_use().len();
        assert!((share_at_the_commonest(all) - 1.0).abs() < f64::EPSILON);
    }
}
